# ----- import.R -----
# Elcometer exports mix metadata, summary statistics and time-series rows.
# Preserve Excel cell types so dates are not guessed from formatted strings.
cell_text <- function(x) {
  if (!length(x) || all(is.na(x))) return("")
  trimws(as.character(x[[1]]))
}

cell_number <- function(x) {
  if (!length(x) || all(is.na(x)) || inherits(x, "POSIXt")) return(NA_real_)
  if (is.numeric(x)) return(as.numeric(x[[1]]))
  suppressWarnings(as.numeric(trimws(as.character(x[[1]]))))
}

cell_timestamp <- function(x) {
  if (!length(x) || all(is.na(x))) return(NA_real_)
  if (inherits(x, "POSIXt")) return(as.numeric(x[[1]]))
  if (inherits(x, "Date")) return(as.numeric(as.POSIXct(x[[1]], tz = "UTC")))
  # Fallback for Excel serials stored as numbers/text (1900 date system).
  # Normal date-formatted cells are already decoded by readxl, including 1904 dates.
  value <- cell_number(x)
  if (is.finite(value) && value > 10000 && value < 100000) {
    return(as.numeric(as.POSIXct("1899-12-30", tz = "UTC")) + value * 86400)
  }
  text <- cell_text(x)
  for (fmt in c("%Y-%m-%d %H:%M:%OS", "%Y/%m/%d %H:%M:%OS",
                "%Y-%m-%dT%H:%M:%OS")) {
    value <- suppressWarnings(as.POSIXct(strptime(text, fmt, tz = "UTC")))
    if (length(value) && !is.na(value)) return(as.numeric(value))
  }
  NA_real_
}

parse_elcometer_sheet <- function(raw, file_name, sheet_name) {
  if (nrow(raw) < 3 || ncol(raw) < 3) stop("The worksheet is too small.")
  row_text <- function(i) vapply(raw, function(col) cell_text(col[[i]]), character(1))
  header_row <- NA_integer_
  channel_cols <- integer()
  time_col <- integer()
  number_col <- integer()
  for (i in seq_len(nrow(raw))) {
    row <- row_text(i)
    channel_cols <- grep("^Ch\\s*[0-9]+\\s*\\(", row, ignore.case = TRUE, perl = TRUE)
    time_col <- which(tolower(row) %in% c("date & time", "date and time"))
    number_col <- which(tolower(row) == "number")
    if (length(channel_cols) && length(time_col) == 1 && length(number_col) == 1) {
      header_row <- i
      break
    }
  }
  if (is.na(header_row)) stop("No Elcometer readings table found (Number, Date & Time, Ch1...).")
  if (header_row == nrow(raw)) stop("The readings table is empty.")
  headers <- row_text(header_row)
  # Reject Fahrenheit rather than silently labelling it Celsius.
  if (any(grepl("F", headers[channel_cols], ignore.case = TRUE))) {
    stop("Fahrenheit exports are not supported. Export temperatures in Celsius.")
  }
  if (any(!grepl("C\\s*\\)", headers[channel_cols], ignore.case = TRUE))) {
    stop("Channel headings must specify Celsius, for example Ch1 (°C).")
  }
  candidates <- seq.int(header_row + 1L, nrow(raw))
  numbers <- vapply(candidates, function(i) cell_number(raw[[number_col]][[i]]), numeric(1))
  reading_rows <- candidates[is.finite(numbers)]
  numbers <- numbers[is.finite(numbers)]
  if (length(reading_rows) < 2) stop("At least two numbered readings are required.")
  ts <- vapply(reading_rows, function(i) cell_timestamp(raw[[time_col]][[i]]), numeric(1))
  if (any(!is.finite(ts))) stop("A reading has an invalid date/time. Check the Date & Time column.")
  # Round sub-millisecond Excel floating-point noise, not the sample interval.
  ts <- round(ts, 3)
  if (any(diff(ts) <= 0)) stop("Reading timestamps must increase strictly; duplicates or reversed times were found.")
  time <- as.POSIXct(ts, origin = "1970-01-01", tz = "UTC")
  elapsed <- (ts - ts[1]) / 60
  get_meta <- function(label) {
    for (i in seq_len(header_row - 1L)) {
      row <- row_text(i)
      if (tolower(row[1]) == tolower(label)) {
        vals <- row[-1]; vals <- vals[nzchar(vals)]
        return(if (length(vals)) vals[1] else "")
      }
    }
    ""
  }
  project <- get_meta("Name")
  if (!nzchar(project)) project <- tools::file_path_sans_ext(file_name)
  expected_step <- stats::median(diff(ts))
  segment_gap <- c(FALSE, diff(ts) > expected_step * 1.5 + 0.001)
  records <- list(); labels <- character(); notes <- character()
  for (col in channel_cols) {
    channel <- paste0("Ch", sub("^Ch\\s*([0-9]+).*", "\\1", headers[col], ignore.case = TRUE, perl = TRUE))
    if (channel %in% names(labels)) stop("Duplicate channel columns were found.")
    vals <- vapply(reading_rows, function(i) cell_number(raw[[col]][[i]]), numeric(1))
    nonblank <- vapply(reading_rows, function(i) nzchar(cell_text(raw[[col]][[i]])), logical(1))
    bad <- nonblank & !is.finite(vals)
    if (any(bad)) notes <- c(notes, paste(channel, "contains", sum(bad), "non-numeric reading(s); shown as gaps."))
    vals[!is.finite(vals)] <- NA_real_
    if (!any(is.finite(vals))) next
    sensor <- get_meta(paste("Channel", sub("Ch", "", channel)))
    labels[channel] <- if (nzchar(sensor)) paste(channel, sensor, sep = " - ") else paste(channel, "(unlabelled)")
    # Split lines after missing readings and larger-than-normal sampling gaps.
    breaks <- segment_gap | !is.finite(vals) | c(FALSE, !is.finite(head(vals, -1)))
    records[[channel]] <- data.frame(reading = numbers, timestamp = time,
      elapsed_min = elapsed, channel = channel, temperature_c = vals,
      segment = cumsum(breaks), stringsAsFactors = FALSE)
  }
  if (!length(records)) stop("No numeric channel temperatures were found.")
  if (any(segment_gap)) notes <- c(notes, "Long sampling gaps are displayed as breaks in the curves.")
  data <- do.call(rbind, records); rownames(data) <- NULL
  list(file_name = basename(file_name), sheet_name = sheet_name, project = project,
       device = get_meta("Type"), labels = labels, data = data,
       start = time[1], end = tail(time, 1), duration = tail(elapsed, 1),
       reading_count = length(time), interval_seconds = expected_step,
       notes = unique(notes), raw = raw, header_row = header_row,
       source_layout = list(merges=list(), widths=numeric(), heights=numeric(), cells=matrix(numeric(),0,3), formats=character()),
       all_channels = paste0("Ch", sub("^Ch\\s*([0-9]+).*", "\\1", headers[channel_cols], ignore.case = TRUE, perl = TRUE)),
       source_summary = extract_workbook_summary(raw, header_row)$summary,
       settings = extract_workbook_summary(raw, header_row)$settings,
       comments = {
         col <- which(tolower(headers) %in% c("comment", "comments"))
         if (length(col)) vapply(reading_rows, function(i) cell_text(raw[[col[1]]][[i]]), character(1)) else rep("", length(reading_rows))
       })
}

read_elcometer_workbook <- function(path, file_name = basename(path)) {
  if (!tolower(tools::file_ext(file_name)) %in% c("xls", "xlsx")) {
    stop("Only .xls and .xlsx workbooks are supported.")
  }
  sheets <- readxl::excel_sheets(path)
  layouts <- read_source_layouts(path, file_name, sheets)
  results <- list(); errors <- character()
  for (sheet in sheets) {
    parsed <- tryCatch({
      raw <- suppressWarnings(readxl::read_excel(path, sheet = sheet,
        col_names = FALSE, col_types = "list", trim_ws = FALSE,
        range = readxl::cell_limits(c(1,1),c(NA,NA)), .name_repair = "minimal"))
      parsed <- parse_elcometer_sheet(raw, file_name, sheet)
      parsed$source_path <- path
      parsed$source_layout <- layouts[[match(sheet,sheets)]]
      parsed
    }, error = function(e) e)
    if (inherits(parsed, "error")) {
      errors <- c(errors, paste0(file_name, " / ", sheet, ": ", conditionMessage(parsed)))
    } else results[[length(results) + 1L]] <- parsed
  }
  list(results = results, errors = errors)
}

# Source values are kept separate from newly computed statistics.
extract_workbook_summary <- function(raw, readings_header) {
  text_row <- function(i) vapply(raw, function(col) cell_text(col[[i]]), character(1))
  before <- if (readings_header > 1) seq_len(readings_header - 1L) else integer()
  candidates <- before[vapply(before, function(i) sum(grepl("^Ch[0-9]+$", text_row(i), ignore.case = TRUE)) >= 2, logical(1))]
  summary_header <- if (length(candidates)) tail(candidates, 1) else NA_integer_
  settings_end <- if (is.na(summary_header)) readings_header - 1L else summary_header - 1L
  settings <- list()
  if (settings_end > 0) for (i in seq_len(settings_end)) {
    row <- text_row(i)
    if (nzchar(row[1])) settings[[length(settings) + 1L]] <- data.frame(
      Setting = row[1], Value = paste(row[-1][nzchar(row[-1])], collapse = " | "), stringsAsFactors = FALSE)
  }
  settings <- if (length(settings)) do.call(rbind, settings) else data.frame(Setting = character(), Value = character())
  if (is.na(summary_header)) return(list(summary = data.frame(), settings = settings))
  hdr <- text_row(summary_header)
  cols <- grep("^Ch[0-9]+$", hdr, ignore.case = TRUE)
  ch <- sub("^ch", "Ch", hdr[cols], ignore.case = TRUE)
  rows <- list()
  if (summary_header + 1L < readings_header) for (i in seq.int(summary_header + 1L, readings_header - 1L)) {
    metric <- cell_text(raw[[1]][[i]])
    if (!nzchar(metric)) next
    units <- vapply(cols, function(j) if (j < ncol(raw) && !(j + 1L) %in% cols) cell_text(raw[[j + 1L]][[i]]) else "", character(1))
    common <- unique(units[nzchar(units)])
    row <- data.frame(Metric = metric, Unit = if (length(common) == 1) common else if (length(common) > 1) "See values" else "", stringsAsFactors = FALSE)
    for (k in seq_along(cols)) {
      x <- raw[[cols[k]]][[i]]
      value <- if (is.numeric(x) && !inherits(x, "POSIXt") && length(x) && is.finite(x[1])) sprintf("%.10g", x[1]) else cell_text(x)
      if (length(common) > 1 && nzchar(units[k])) value <- paste(value, units[k])
      row[[ch[k]]] <- value
    }
    rows[[length(rows) + 1L]] <- row
  }
  list(summary = if (length(rows)) do.call(rbind, rows) else data.frame(), settings = settings)
}

record_matrix <- function(record) {
  channels <- record$all_channels
  m <- matrix(NA_real_, nrow = record$reading_count, ncol = length(channels), dimnames = list(NULL, channels))
  for (ch in names(record$labels)) m[, ch] <- record$data$temperature_c[record$data$channel == ch]
  m
}

reading_data <- function(record, channels = record$all_channels) {
  time <- record$data[record$data$channel == names(record$labels)[1], ]
  out <- data.frame(Reading = time$reading,
    Timestamp = format(time$timestamp, "%Y-%m-%d %H:%M:%S", tz = "UTC"),
    Elapsed_min = round(time$elapsed_min, 6), check.names = FALSE)
  m <- record_matrix(record)
  for (ch in channels) out[[paste0(ch, "_C")]] <- m[, ch]
  out$Comment <- record$comments
  out
}

valid_intervals <- function(record, x) {
  time <- record$data$elapsed_min[record$data$channel == names(record$labels)[1]]
  dt <- diff(time)
  good <- is.finite(head(x, -1)) & is.finite(tail(x, -1)) &
    dt > 0 & dt <= record$interval_seconds / 60 * 1.5 + .001 / 60
  list(dt = dt, good = good, left = head(x, -1), right = tail(x, -1))
}

time_above <- function(record, x, threshold) {
  z <- valid_intervals(record, x)
  if (!any(z$good)) return(NA_real_)
  a <- z$left[z$good]; b <- z$right[z$good]; dt <- z$dt[z$good]
  fraction <- numeric(length(a))
  fraction[a > threshold & b > threshold] <- 1
  crossing <- (a > threshold) != (b > threshold)
  fraction[crossing] <- (pmax(a[crossing], b[crossing]) - threshold) / abs(b[crossing] - a[crossing])
  sum(dt * fraction)
}

workbook_threshold <- function(record, label) {
  rows <- record$settings
  match <- which(tolower(rows$Setting) == tolower(label))
  if (!length(match)) return(NA_real_)
  value <- trimws(rows$Value[match[1]])
  # Only an explicit scalar Celsius setting is accepted; never infer cure limits.
  if (!grepl("^[+-]?[0-9]+([.][0-9]+)?\\s*°?\\s*C$", value, ignore.case = TRUE)) return(NA_real_)
  suppressWarnings(as.numeric(sub("\\s*°?\\s*C$", "", value, ignore.case = TRUE)))
}

channel_summary <- function(record) {
  m <- record_matrix(record); channels <- colnames(m)
  time <- record$data[record$data$channel == names(record$labels)[1], ]
  active <- names(record$labels)
  spread <- rep(NA_real_, nrow(m))
  if (length(active) >= 2) {
    complete <- rowSums(is.finite(m[, active, drop = FALSE])) == length(active)
    spread[complete] <- apply(m[complete, active, drop = FALSE], 1, function(x) max(x) - min(x))
  }
  peak_index <- function(x) if (any(is.finite(x))) which.max(replace(x, !is.finite(x), -Inf)) else NA_integer_
  all_peak <- peak_index(spread)
  at <- function(x, i) if (is.na(i)) NA_real_ else x[i]
  metric <- c("# Readings", "Missing readings", "Mean", "Median", "Maximum", "Minimum",
    "Range", "Standard Deviation (sample, n-1)", "Coefficient of Variation",
    "Elapsed time of first maximum", "Reading at first maximum", "Elapsed time of first minimum",
    "Peak Difference (across all active channels)", "Elapsed time of Peak Difference (all)",
    "Reading at Peak Difference (all)", "Peak Difference (to other active channels)",
    "Elapsed time of Peak Difference (other)", "Reading at Peak Difference (other)",
    "Mean simultaneous spread (all active channels)", "Recorded duration", "Valid interval coverage",
    "Time-weighted mean", "Maximum heating rate", "Maximum cooling rate")
  unit <- c("count", "count", rep("°C", 6), "%", "min", "reading", "min", "°C", "min", "reading",
    "°C", "min", "reading", "°C", "min", "min", "°C", "°C/min", "°C/min")
  out <- data.frame(Metric = metric, Unit = unit, stringsAsFactors = FALSE)
  for (ch in channels) {
    x <- m[, ch]; finite <- is.finite(x); n <- sum(finite); v <- x[finite]
    if (!n) { out[[ch]] <- c(0, nrow(m), rep(NA_real_, length(metric) - 2)); next }
    mean_x <- mean(v); sd_x <- if (n > 1) stats::sd(v) else NA_real_
    high <- peak_index(x); low <- peak_index(-x)
    other <- setdiff(active, ch); pair <- rep(NA_real_, nrow(m))
    if (length(other)) for (i in which(finite)) {
      distances <- abs(x[i] - m[i, other]); distances <- distances[is.finite(distances)]
      if (length(distances)) pair[i] <- max(distances)
    }
    p <- peak_index(pair); z <- valid_intervals(record, x)
    coverage <- sum(z$dt[z$good])
    rate <- (z$right[z$good] - z$left[z$good]) / z$dt[z$good]
    weighted <- if (coverage > 0) sum(z$dt[z$good] * (z$left[z$good] + z$right[z$good]) / 2) / coverage else NA_real_
    values <- c(n, sum(!finite), mean_x, stats::median(v), max(v), min(v), diff(range(v)), sd_x,
      if (abs(mean_x) > 1e-12) 100 * sd_x / abs(mean_x) else NA_real_,
      at(time$elapsed_min, high), at(time$reading, high), at(time$elapsed_min, low),
      at(spread, all_peak), at(time$elapsed_min, all_peak), at(time$reading, all_peak),
      at(pair, p), at(time$elapsed_min, p), at(time$reading, p),
      if (any(is.finite(spread))) mean(spread, na.rm = TRUE) else NA_real_, record$duration,
      coverage, weighted, if (length(rate)) max(0, rate) else NA_real_, if (length(rate)) max(0, -rate) else NA_real_)
    out[[ch]] <- round(values, 4)
  }
  for (label in c("Maximum Temperature", "Minimum Temperature")) {
    limit <- workbook_threshold(record, label)
    if (!is.finite(limit)) next
    row <- data.frame(Metric = paste0("Time above workbook ", tolower(label), " (", limit, " °C)"), Unit = "min", stringsAsFactors = FALSE)
    for (ch in channels) row[[ch]] <- round(time_above(record, m[, ch], limit), 4)
    out <- rbind(out, row)
  }
  out
}

summary_method <- paste(
  "Calculated from readings for all workbook channels. Empty channels have 0 readings and unavailable statistics.",
  "SD uses n-1; CV = 100 x SD / abs(mean in Celsius), a temperature-scale-dependent instrument statistic.",
  "Peak differences compare simultaneous readings across all active channels, including hidden channels.",
  "All-channel spread requires a valid reading on every active channel. Ties use the first occurrence.",
  "Calculated times are elapsed minutes; reading numbers are listed separately.",
  "Time-weighted values, slopes and times above explicit workbook limits use linear intervals, excluding missing data and long gaps.")

source_method <- paste(
  "Copied from the uploaded workbook, including all summary rows and inactive-channel values.",
  "Cure values, Pass/Fail and source threshold durations are reported results, not a new evaluation by this app.",
  "Source time fields retain their original values; their units are not inferred.")

clean_unused_drawing_links <- function(file) {
  # Some openxlsx releases leave unused drawing/VML relationships on sheets
  # without images. Remove only unreferenced links to non-existent parts.
  folder <- tempfile("xlsx_parts_"); dir.create(folder)
  rebuilt <- tempfile(fileext = ".xlsx")
  on.exit(unlink(c(folder, rebuilt), recursive = TRUE), add = TRUE)
  utils::unzip(file, exdir = folder)
  changed <- FALSE
  rels <- list.files(folder, pattern = "\\.rels$", full.names = TRUE, recursive = TRUE, all.files = TRUE)
  for (path in rels) {
    xml <- paste(readLines(path, warn = FALSE, encoding = "UTF-8"), collapse = "\n")
    links <- regmatches(xml, gregexpr("<Relationship\\b[^>]*/>", xml, perl = TRUE))[[1]]
    old <- xml
    for (link in links) {
      if (!grepl('Type="[^"]+/(drawing|vmlDrawing)"', link, perl = TRUE)) next
      target <- sub('.*Target="([^"]*)".*', '\\1', link)
      if (file.exists(file.path(dirname(dirname(path)), target))) next
      owner <- sub('/_rels/([^/]+)\\.rels$', '/\\1', gsub('\\\\', '/', path))
      id <- sub('.*Id="([^"]*)".*', '\\1', link)
      if (file.exists(owner) && any(grepl(paste0('r:id="', id, '"'), readLines(owner, warn = FALSE), fixed = TRUE))) {
        stop("An image referenced by the Excel report is missing.")
      }
      xml <- sub(link, "", xml, fixed = TRUE)
    }
    if (!identical(xml, old)) { writeLines(xml, path, useBytes = TRUE); changed <- TRUE }
  }
  if (changed) {
    zip::zip(rebuilt, files = list.files(folder, recursive = TRUE, all.files = TRUE, no.. = TRUE),
      root = folder, include_directories = FALSE, mode = "mirror")
    if (!file.copy(rebuilt, file, overwrite = TRUE)) stop("Could not finalize the Excel report.")
  }
  invisible(file)
}

# ----- charts.R -----
channel_colors <- c(Ch1 = "#167F83", Ch2 = "#D08B4F", Ch3 = "#526AC1",
                    Ch4 = "#9C5B83", Ch5 = "#657C3C", Ch6 = "#B75151")

profile_colors <- function(channels) {
  colors <- channel_colors[channels]
  unknown <- is.na(colors)
  if (any(unknown)) {
    index <- suppressWarnings(as.numeric(sub("Ch", "", channels[unknown])))
    colors[unknown] <- grDevices::hsv((index * 0.61803398875) %% 1, .65, .72)
  }
  stats::setNames(colors, channels)
}

plotly_profile <- function(record, channels, stage) {
  colors <- profile_colors(channels)
  p <- plotly::plot_ly()
  selected <- record$data[record$data$channel %in% channels, ]
  for (ch in channels) {
    d <- selected[selected$channel == ch, ]
    first <- TRUE
    for (seg in unique(d$segment)) {
      part <- d[d$segment == seg & is.finite(d$temperature_c), ]
      if (!nrow(part)) next
      tooltip <- paste0(ch, "<br>", sprintf("%.2f", part$elapsed_min), " min",
        "<br>", sprintf("%.1f", part$temperature_c), " C",
        "<br>", format(part$timestamp, "%H:%M:%S", tz = "UTC"))
      p <- plotly::add_trace(p, x = part$elapsed_min, y = part$temperature_c,
        type = "scatter", mode = if (nrow(part) == 1) "markers" else "lines",
        name = ch, legendgroup = ch, showlegend = first,
        line = list(color = unname(colors[ch]), width = 2.8),
        marker = list(color = unname(colors[ch]), size = 6),
        text = tooltip, hoverinfo = "text", connectgaps = FALSE)
      first <- FALSE
    }
  }
  finite <- selected[is.finite(selected$temperature_c), ]
  peak <- finite[which.max(finite$temperature_c), ]
  span <- max(1, diff(range(finite$temperature_c)))
  p <- plotly::layout(p,
    xaxis = list(title = "Elapsed time from first reading (min)", range = c(0, record$duration),
                 gridcolor = "#E7EBF0", zeroline = FALSE),
    yaxis = list(title = "Recorded temperature (°C)", gridcolor = "#E7EBF0", zeroline = FALSE,
      range = c(min(finite$temperature_c) - span * .08, max(finite$temperature_c) + span * .14)),
    font = list(family = "Arial, sans-serif", color = "#243247", size = 13),
    paper_bgcolor = "#FFFFFF", plot_bgcolor = "#FFFFFF",
    margin = list(l = 68, r = 25, t = 48, b = 88), hovermode = "closest",
    legend = list(orientation = "h", x = .5, xanchor = "center", y = -.2),
    annotations = list(list(x = peak$elapsed_min, y = peak$temperature_c,
      text = sprintf("Peak: %.1f C (%s)", peak$temperature_c, peak$channel),
      showarrow = TRUE, arrowhead = 2, ax = if (peak$elapsed_min > record$duration / 2) -65 else 65,
      ay = -38, font = list(size = 12, color = "#243247"))))
  plotly::config(p, displaylogo = FALSE, responsive = TRUE,
    modeBarButtonsToRemove = c("lasso2d", "select2d", "toImage"), scrollZoom = FALSE)
}

save_profile_png <- function(file, record, channels, stage) {
  colors <- profile_colors(channels)
  grDevices::png(file, width = 1800, height = 1000, res = 160)
  on.exit(grDevices::dev.off(), add = TRUE)
  graphics::layout(matrix(c(1, 2), ncol = 1), heights = c(.9, .1))
  graphics::par(mar = c(4.5, 5, 4.5, 1.5), family = "sans")
  d <- record$data[record$data$channel %in% channels, ]
  finite <- d[is.finite(d$temperature_c), ]
  span <- max(1, diff(range(finite$temperature_c)))
  yr <- range(finite$temperature_c) + c(-.08, .18) * span
  graphics::plot(NA, xlim = c(0, record$duration), ylim = yr,
    xlab = "Elapsed time from first reading (min)", ylab = "Recorded temperature (C)",
    main = paste(stage, "temperature profile |", record$project), bty = "l", las = 1)
  graphics::mtext(paste(format(record$start, "%H:%M:%S", tz = "UTC"), "-",
    format(record$end, "%H:%M:%S", tz = "UTC")), side = 3, line = .4, cex = .85)
  graphics::grid(col = "#E7EBF0")
  for (ch in channels) {
    part <- d[d$channel == ch, ]
    for (seg in unique(part$segment)) {
      piece <- part[part$segment == seg & is.finite(part$temperature_c), ]
      if (!nrow(piece)) next
      if (nrow(piece) == 1) graphics::points(piece$elapsed_min, piece$temperature_c, col = colors[ch], pch = 16)
      else graphics::lines(piece$elapsed_min, piece$temperature_c, col = colors[ch], lwd = 2.3)
    }
  }
  peak <- finite[which.max(finite$temperature_c), ]
  graphics::points(peak$elapsed_min, peak$temperature_c, pch = 21, bg = "white", col = "#243247", cex = 1.1)
  graphics::text(peak$elapsed_min, peak$temperature_c + span * .075,
    labels = sprintf("Peak: %.1f C (%s)", peak$temperature_c, peak$channel),
    adj = c(if (peak$elapsed_min < record$duration * .2) 0 else if (peak$elapsed_min > record$duration * .8) 1 else .5, .5), cex = .8)
  graphics::par(mar = c(0, 0, 0, 0))
  graphics::plot.new()
  graphics::legend("center", legend = channels, col = colors[channels], lwd = 2.3,
                   horiz = TRUE, bty = "n", cex = .9)
}


# Retain worksheet cells and layout. BIFF metadata is read locally in base R;
# readxl remains responsible for decoding actual .xls values and dates.
u16 <- function(b, offset = 0L) sum(as.numeric(b[offset + 1:2]) * c(1, 256))
u32 <- function(b, offset = 0L) sum(as.numeric(b[offset + 1:4]) * c(1, 256, 65536, 16777216))
utf16le <- function(b) {
  if (!length(b)) return("")
  z <- as.numeric(b); v <- z[seq(1,length(z),2)] + 256*z[seq(2,length(z),2)]
  out <- integer(); i <- 1L
  while (i <= length(v)) {
    n <- v[i]
    if (n >= 55296 && n <= 56319 && i < length(v) && v[i+1] >= 56320 && v[i+1] <= 57343) {
      n <- 65536 + (n-55296)*1024 + v[i+1]-56320; i <- i+1L
    }
    if (n > 0) out <- c(out,n)
    i <- i+1L
  }
  intToUtf8(out)
}
xls_layouts <- function(path) {
  b <- readBin(path, "raw", n = file.info(path)$size)
  if (length(b)<512 || !identical(as.integer(b[1:8]), c(208L,207L,17L,224L,161L,177L,26L,225L)))
    stop("The .xls file is not an OLE/BIFF workbook.")
  size <- 2^u16(b,30); mini_size <- 2^u16(b,32)
  sector <- function(id) {
    at <- (id+1)*size
    if (id >= 4294967290 || at+size>length(b)) stop("Invalid XLS sector.")
    b[at+seq_len(size)]
  }
  ints <- function(x) { v <- as.numeric(readBin(x,"integer",n=length(x)/4,size=4,endian="little")); v[v<0] <- v[v<0]+2^32; v }
  fat_ids <- ints(b[77:512]); id <- u32(b,68)
  for (i in seq_len(u32(b,72))) { d <- ints(sector(id)); fat_ids <- c(fat_ids,head(d,-1)); id <- tail(d,1) }
  fat_ids <- fat_ids[fat_ids<4294967290]
  fat <- unlist(lapply(fat_ids,function(id) ints(sector(id))),use.names=FALSE)
  chain <- function(id, table, fetch) {
    chunks <- list(); seen <- logical(length(table))
    while (id<4294967290) {
      if (id+1>length(table) || seen[id+1]) stop("Invalid XLS sector chain.")
      seen[id+1] <- TRUE; chunks[[length(chunks)+1L]] <- fetch(id); id <- table[id+1]
    }
    do.call(c,chunks)
  }
  directory <- chain(u32(b,48),fat,sector)
  entries <- lapply(seq(0,length(directory)-128,128),function(i) {
    d <- directory[i+1:128]; n <- u16(d,64)
    list(name=if(n>2) utf16le(d[seq_len(n-2)]) else "", type=as.integer(d[67]),
         start=u32(d,116), size=u32(d,120))
  })
  found <- which(vapply(entries,function(e) e$name %in% c("Workbook","Book"),logical(1)))
  if (!length(found)) stop("No XLS workbook stream.")
  stream <- entries[[found[1]]]
  if (stream$size < u32(b,56)) {
    root <- entries[[which(vapply(entries,function(e) e$type==5,logical(1)))[1]]]
    mini <- chain(root$start,fat,sector)
    mini_fat <- ints(chain(u32(b,60),fat,sector))
    bytes <- chain(stream$start,mini_fat,function(id) mini[id*mini_size+seq_len(mini_size)])
  } else bytes <- chain(stream$start,fat,sector)
  bytes <- bytes[seq_len(stream$size)]
  records_at <- function(start) {
    ans <- list(); pos <- start
    while (pos+4<=length(bytes)) {
      type <- u16(bytes,pos); n <- u16(bytes,pos+2)
      if (pos+4+n>length(bytes)) stop("Truncated BIFF record.")
      ans[[length(ans)+1L]] <- list(type=type, data=if(n) bytes[pos+4+seq_len(n)] else raw())
      pos <- pos+4+n
      if (type==10) break
    }
    ans
  }
  globals <- records_at(0); offsets <- numeric(); xf <- integer(); formats <- list(); xf_raw <- list(); fonts <- list()
  for (rec in globals) {
    d <- rec$data
    if (rec$type==133) offsets <- c(offsets,u32(d,0))
    if (rec$type==49) {
      n <- as.integer(d[15]); wide <- bitwAnd(as.integer(d[16]),1)!=0
      name <- if(wide) utf16le(d[16+seq_len(n*2)]) else intToUtf8(as.integer(d[16+seq_len(n)]))
      fonts[[length(fonts)+1L]] <- list(fontName=name,fontSize=u16(d,0)/20,
        textDecoration=c(if(u16(d,6)>=700) "bold",if(bitwAnd(u16(d,2),2)) "italic",if(as.integer(d[11])>0) "underline"))
    }
    if (rec$type==224) { xf <- c(xf,u16(d,2)); xf_raw[[length(xf_raw)+1L]] <- d }
    if (rec$type==1054) {
      n <- u16(d,2); flag <- as.integer(d[5]); start <- 5L
      if (bitwAnd(flag,8)) start <- start+2L
      if (bitwAnd(flag,4)) start <- start+4L
      wide <- bitwAnd(flag,1)!=0
      text <- if (!n) "" else if(wide) utf16le(d[start+seq_len(n*2)]) else intToUtf8(as.integer(d[start+seq_len(n)]))
      formats[[as.character(u16(d,0))]] <- text
    }
  }
  builtin <- c('0'='General','1'='0','2'='0.00','3'='#,##0','4'='#,##0.00',
    '9'='0%','10'='0.00%','11'='0.00E+00','14'='mm-dd-yy','15'='d-mmm-yy',
    '16'='d-mmm','17'='mmm-yy','18'='h:mm AM/PM','19'='h:mm:ss AM/PM',
    '20'='h:mm','21'='h:mm:ss','22'='m/d/yy h:mm','45'='mm:ss','46'='[h]:mm:ss','47'='mmss.0','49'='@')
  lapply(offsets,function(offset) {
    merges <- list(); cells <- list(); widths <- numeric(); heights <- numeric()
    for(rec in records_at(offset)) {
      d <- rec$data; type <- rec$type
      if (type==229) for(k in seq_len(u16(d))) {
        start <- 2+(k-1)*8
        merges[[length(merges)+1L]] <- c(u16(d,start)+1,u16(d,start+2)+1,u16(d,start+4)+1,u16(d,start+6)+1)
      }
      if (type==125) for(col in seq.int(u16(d,0),u16(d,2))) widths[as.character(col+1)] <- u16(d,4)/256
      if (type==520) heights[as.character(u16(d,0)+1)] <- bitwAnd(u16(d,6),32767)/20
      if (type %in% c(515,638,253,6,517,513,516)) cells[[length(cells)+1L]] <- c(u16(d,0)+1,u16(d,2)+1,u16(d,4)+1)
      if (type %in% c(189,190)) {
        first <- u16(d,2); last <- u16(d,length(d)-2); step <- if(type==189) 6 else 2
        for(col in seq.int(first,last)) cells[[length(cells)+1L]] <- c(u16(d,0)+1,col+1,u16(d,4+(col-first)*step)+1)
      }
    }
    cells <- if(length(cells)) do.call(rbind,cells) else matrix(numeric(),0,3)
    numfmts <- vapply(xf,function(id) { s <- formats[[as.character(id)]]; if(!is.null(s)) s else if(as.character(id) %in% names(builtin)) unname(builtin[as.character(id)]) else "General" },character(1))
    styles <- lapply(seq_along(xf_raw),function(i) {
      d <- xf_raw[[i]]; font_id <- u16(d,0); fi <- if(font_id>=4) font_id else font_id+1
      args <- if(fi<=length(fonts)) fonts[[fi]] else list()
      if(!length(args$textDecoration)) args$textDecoration <- NULL
      a <- as.integer(d[7]); h <- bitwAnd(a,7); v <- bitwAnd(bitwShiftR(a,4),7)
      args$halign <- switch(as.character(h),'1'='left','2'='center','3'='right','5'='justify',NULL)
      args$valign <- switch(as.character(v),'0'='top','1'='center','2'='bottom',NULL)
      args$wrapText <- bitwAnd(a,8)!=0; args$numFmt <- numfmts[i]
      border <- u32(d,10); codes <- floor(border/16^(0:3))%%16
      choices <- c('none','thin','medium','dashed','dotted','thick','double','hair','mediumDashed','dashDot','mediumDashDot','dashDotDot','mediumDashDotDot','slantDashDot')
      use <- which(codes>0 & codes<length(choices))
      if(length(use)) { args$border <- c('left','right','top','bottom')[use]; args$borderStyle <- choices[codes[use]+1]; args$borderColour <- '#B7C8D3' }
      args
    })
    list(merges=merges, widths=widths, heights=heights, cells=cells, formats=numfmts, styles=styles)
  })
}

source_value <- function(x) {
  if (!length(x) || all(is.na(x))) return("")
  if (inherits(x,"POSIXt")) return(format(x[[1]],"%Y-%m-%d %H:%M:%S",tz="UTC"))
  if (is.numeric(x)) return(sprintf("%.12g",x[[1]]))
  as.character(x[[1]])
}
source_sections <- function(record) {
  raw <- record$raw
  rows <- lapply(seq_len(nrow(raw)),function(i) vapply(raw,function(col) source_value(col[[i]]),character(1)))
  occupied <- vapply(rows,function(x) any(nzchar(x)),logical(1))
  titles <- integer()
  for (m in record$source_layout$merges) {
    if(m[1]==m[2] && m[3]==1 && m[4]>=ncol(raw)-1 && occupied[m[1]]) titles <- c(titles,m[1])
  }
  known <- c("Project","Gauge","Batch","Paint Type","Logger","Triggers","Note")
  for(i in seq_len(nrow(raw))) if (sum(nzchar(rows[[i]]))==1 && trimws(rows[[i]][1]) %in% known) titles <- c(titles,i)
  summary <- which(vapply(rows,function(x) sum(grepl("^Ch[0-9]+$",x))>=2,logical(1)))
  starts <- sort(unique(c(1L,titles,summary,record$header_row)))
  ends <- c(starts[-1]-1L,nrow(raw))
  lapply(seq_along(starts),function(k) {
    start <- starts[k]
    kind <- if(start==record$header_row) "readings" else if(start %in% summary) "summary" else "metadata"
    title <- if(kind=="readings") "Readings" else if(kind=="summary") "Channel summary — from workbook" else if(start %in% titles) rows[[start]][1] else "Worksheet content"
    list(title=title, start=start, end=ends[k], kind=kind, title_row=start %in% titles)
  })
}
source_table_ui <- function(record, section) {
  raw <- record$raw; nr <- nrow(raw); nc <- ncol(raw)
  merges <- record$source_layout$merges
  occupied <- matrix(FALSE,nr,nc); top <- list()
  for(m in merges) if(m[2]<=nr && m[4]<=nc) {
    occupied[m[1]:m[2],m[3]:m[4]] <- TRUE
    occupied[m[1],m[3]] <- FALSE; top[[paste(m[1],m[3])]] <- m
  }
  idx <- seq.int(section$start,section$end)
  if(section$title_row) idx <- idx[idx!=section$start]
  # Every source cell is retained; HTML escaping is supplied by Shiny tags.
  body <- lapply(idx,function(i) shiny::tags$tr(lapply(seq_len(nc),function(j) {
    if(occupied[i,j]) return(NULL)
    m <- top[[paste(i,j)]]; text <- source_value(raw[[j]][[i]])
    tag <- if(i==record$header_row || (section$kind=="summary" && i==section$start)) shiny::tags$th else shiny::tags$td
    tag(rowspan=if(!is.null(m)) m[2]-m[1]+1 else NULL,
        colspan=if(!is.null(m)) m[4]-m[3]+1 else NULL,text)
  })))
  shiny::div(class=paste("source-grid",if(section$kind=="readings") "source-readings" else ""),
    shiny::tags$table(class="table",shiny::tags$tbody(body)))
}

read_source_layouts <- function(path,file_name,sheets) {
  if(tolower(tools::file_ext(file_name))=="xls") return(xls_layouts(path))
  wb <- openxlsx::loadWorkbook(path)
  lapply(seq_along(sheets),function(i) {
    xml <- wb$worksheets[[i]]$mergeCells
    merges <- lapply(xml,function(x) {
      ref <- sub('.*ref="([^"]+)".*','\\1',x)
      a <- strsplit(ref,":",fixed=TRUE)[[1]]; if(length(a)==1) a <- rep(a,2)
      rows <- as.integer(gsub("[^0-9]","",a)); cols <- openxlsx::col2int(gsub("[^A-Z]","",toupper(a)))
      c(rows[1],rows[2],cols[1],cols[2])
    })
    list(merges=merges,widths=numeric(),heights=numeric(),cells=matrix(numeric(),0,3),formats=character())
  })
}

write_source_sheet <- function(record) {
  raw <- record$raw; layout <- record$source_layout
  is_xlsx <- !is.null(record$source_path) && tolower(tools::file_ext(record$file_name))=="xlsx"
  if(is_xlsx) {
    wb <- openxlsx::loadWorkbook(record$source_path)
    sheet <- record$sheet_name
    for(other in setdiff(names(wb),sheet)) openxlsx::removeWorksheet(wb,other)
  } else {
    wb <- openxlsx::createWorkbook(creator="Nazanin Ghaemi-Zadeh")
    sheet <- record$sheet_name; openxlsx::addWorksheet(wb,sheet,gridLines=FALSE)
    for(j in seq_len(ncol(raw))) {
      column <- raw[[j]]
      types <- vapply(column,function(x) if(!length(x)||all(is.na(x))) "blank" else if(inherits(x,"POSIXt")) "date" else if(is.numeric(x)) "number" else if(is.logical(x)) "logical" else "text",character(1))
      runs <- split(seq_along(types),cumsum(c(TRUE,head(types,-1)!=tail(types,-1))))
      for(rows in runs) {
        type <- types[rows[1]]; if(type=="blank") next
        value <- if(type=="date") as.POSIXct(vapply(column[rows],as.numeric,numeric(1)),origin="1970-01-01",tz="UTC") else unlist(column[rows],use.names=FALSE)
        openxlsx::writeData(wb,sheet,value,startRow=rows[1],startCol=j,colNames=FALSE,rowNames=FALSE)
      }
    }
    for(m in layout$merges) openxlsx::mergeCells(wb,sheet,rows=m[1]:m[2],cols=m[3]:m[4])
    if(length(layout$widths)) openxlsx::setColWidths(wb,sheet,cols=as.integer(names(layout$widths)),widths=layout$widths)
    if(length(layout$heights)) openxlsx::setRowHeights(wb,sheet,rows=as.integer(names(layout$heights)),heights=layout$heights)
    cells <- layout$cells
    if(nrow(cells)) for(id in unique(cells[,3])) {
      z <- cells[cells[,3]==id,,drop=FALSE]
      style <- if(length(layout$styles)) do.call(openxlsx::createStyle,layout$styles[[id]]) else openxlsx::createStyle(numFmt=layout$formats[id])
      openxlsx::addStyle(wb,sheet,style,rows=z[,1],cols=z[,2],stack=TRUE)
    }
  }
  # Apply only a new palette: keep source values, coordinates, merges and number formats.
  for(parity in 0:1) {
    rows <- seq_len(nrow(raw)); rows <- rows[rows%%2==parity]
    if(length(rows)) openxlsx::addStyle(wb,sheet,openxlsx::createStyle(fontColour="#20354B",fgFill=if(parity) "#FFFFFF" else "#F0F5F8"),rows=rows,cols=seq_len(ncol(raw)),gridExpand=TRUE,stack=TRUE)
  }
  for(section in source_sections(record)) if(section$title_row || section$kind %in% c("summary","readings")) {
    openxlsx::addStyle(wb,sheet,openxlsx::createStyle(fontColour="#FFFFFF",fgFill="#14283F",textDecoration="bold"),
      rows=section$start,cols=seq_len(ncol(raw)),gridExpand=TRUE,stack=TRUE)
  }
  list(wb=wb,sheet=sheet)
}

# One palette and one set of calculations for the screen, PNG and Excel charts.
spread_data <- function(record,channels) {
  time <- record$data$elapsed_min[record$data$channel==names(record$labels)[1]]
  m <- record_matrix(record)[,channels,drop=FALSE]
  value <- rep(NA_real_,length(time))
  if(length(channels)>=2) {
    good <- rowSums(is.finite(m))==length(channels)
    value[good] <- apply(m[good,,drop=FALSE],1,max)-apply(m[good,,drop=FALSE],1,min)
  }
  gap <- c(FALSE,diff(time)>record$interval_seconds/60*1.5+.001/60)
  data.frame(time=time,value=value,segment=cumsum(gap | !is.finite(value) | c(FALSE,!is.finite(head(value,-1)))))
}
band_data <- function(record,channels) {
  m <- record_matrix(record)[,channels,drop=FALSE]
  finite <- m[is.finite(m)]
  if(!length(finite)) return(NULL)
  width <- max(10,ceiling(diff(range(finite))/30/10)*10)
  lower <- floor(min(finite)/width)*width
  upper <- (floor(max(finite)/width)+1)*width
  edges <- seq(lower,upper,by=width)
  values <- matrix(0,length(edges)-1,length(channels),dimnames=list(NULL,channels))
  coverage <- numeric(length(channels))
  for(j in seq_along(channels)) {
    z <- valid_intervals(record,m[,j]); good <- which(z$good)
    coverage[j] <- sum(z$dt[good])
    if(!length(good)) { values[,j] <- NA_real_; next }
    for(i in good) {
      lo <- min(z$left[i],z$right[i]); hi <- max(z$left[i],z$right[i])
      if(hi==lo) {
        k <- findInterval(lo,edges,rightmost.closed=TRUE)
        values[k,j] <- values[k,j]+z$dt[i]
      } else values[,j] <- values[,j]+z$dt[i]*pmax(0,pmin(hi,tail(edges,-1))-pmax(lo,head(edges,-1)))/(hi-lo)
    }
  }
  list(edges=edges,labels=paste(head(edges,-1),tail(edges,-1),sep="–"),values=values,coverage=coverage,width=width)
}
comparison_records <- function(uploads,records,sheet_name) {
  out <- list()
  for(fid in names(uploads)) {
    ids <- intersect(uploads[[fid]]$ids,names(records)); if(!length(ids)) next
    same <- ids[vapply(records[ids],function(r) identical(r$sheet_name,sheet_name),logical(1))]
    r <- records[[if(length(same)) same[1] else ids[1]]]
    r$upload_id <- fid; out[[fid]] <- r
  }
  out
}
peak_data <- function(records) {
  out <- lapply(seq_along(records),function(i) {
    r <- records[[i]]
    do.call(rbind,lapply(names(r$labels),function(ch) data.frame(index=i,file=r$file_name,sheet=r$sheet_name,channel=ch,
      peak=max(r$data$temperature_c[r$data$channel==ch],na.rm=TRUE),stringsAsFactors=FALSE)))
  })
  if(length(out)) do.call(rbind,out) else data.frame()
}
chart_layout <- function(p,x,y) {
  p <- plotly::layout(p,xaxis=list(title=x,gridcolor="#E5EBF1",zeroline=FALSE),
    yaxis=list(title=y,gridcolor="#E5EBF1",zeroline=FALSE),paper_bgcolor="white",plot_bgcolor="white",
    font=list(family="Arial, sans-serif",color="#20354B",size=12),margin=list(l=65,r=25,t=25,b=60),
    legend=list(orientation="h",x=.5,xanchor="center",y=-.17))
  plotly::config(p,displaylogo=FALSE,responsive=TRUE,modeBarButtonsToRemove=c("toImage","lasso2d","select2d"))
}
plotly_spread <- function(record,channels) {
  d <- spread_data(record,channels); p <- plotly::plot_ly()
  if(length(channels)<2) return(plotly::layout(p,annotations=list(text="Select at least two channels to calculate spread.",showarrow=FALSE,x=.5,y=.5,xref="paper",yref="paper")))
  for(s in unique(d$segment)) {
    z <- d[d$segment==s & is.finite(d$value),]; if(!nrow(z)) next
    p <- plotly::add_trace(p,x=z$time,y=z$value,type="scatter",mode="lines+markers",showlegend=FALSE,
      line=list(color="#167F83",width=2.7),marker=list(size=3,color="#167F83"),fill="tozeroy",fillcolor="rgba(22,127,131,.10)",
      hovertemplate="%{x:.2f} min<br>Spread: %{y:.1f} °C<extra></extra>")
  }
  chart_layout(p,"Elapsed time (min)","Channel spread (°C)")
}
plotly_bands <- function(record,channels) {
  d <- band_data(record,channels)
  p <- plotly::plot_ly(x=channels,y=d$labels,z=d$values,type="heatmap",
    colorscale=list(list(0,"#EDF5F5"),list(1/3,"#83BCB8"),list(2/3,"#167F83"),list(1,"#123C52")),
    zmin=0,zmax=max(1,d$values,na.rm=TRUE),colorbar=list(title="Minutes"),xgap=2,ygap=2,
    hovertemplate="%{x}<br>%{y} °C<br>%{z:.2f} min<extra></extra>")
  grid <- expand.grid(y=d$labels,x=channels,stringsAsFactors=FALSE)
  grid$value <- as.vector(d$values)
  p <- plotly::add_trace(p,data=grid,x=~x,y=~y,text=~ifelse(is.finite(value),sprintf("%.1f",value),"N/A"),
    type="scatter",mode="text",textfont=list(size=12,color=ifelse(is.finite(grid$value) & grid$value>max(1,d$values,na.rm=TRUE)*.5,"white","#14283F")),hoverinfo="skip",showlegend=FALSE,inherit=FALSE)
  p <- chart_layout(p,"Channel","Temperature band (°C)")
  plotly::layout(p,yaxis=list(type="category",categoryorder="array",categoryarray=d$labels),xaxis=list(type="category"))
}
plotly_peaks <- function(records) {
  d <- peak_data(records); p <- plotly::plot_ly()
  channels <- sort(unique(d$channel)); offsets <- if(length(channels)==1) 0 else seq(-.26,.26,length.out=length(channels))
  for(j in seq_along(channels)) {
    z <- d[d$channel==channels[j],]
    p <- plotly::add_trace(p,x=z$peak,y=z$index+offsets[j],type="scatter",mode="markers",name=channels[j],
      marker=list(size=10,color=unname(profile_colors(channels[j]))),
      text=paste(z$file,z$sheet,channels[j],sep="<br>"),hovertemplate="%{text}<br>Peak: %{x:.1f} °C<extra></extra>")
  }
  p <- chart_layout(p,"Peak temperature (°C)","")
  names <- vapply(records,function(r) htmltools::htmlEscape(r$file_name),character(1))
  plotly::layout(p,yaxis=list(tickmode="array",tickvals=seq_along(records),ticktext=names,
    range=c(length(records)+.65,.35),automargin=TRUE),margin=list(l=190,r=25,t=25,b=80))
}

chart_heights <- function(record,channels,records) {
  bands <- band_data(record,channels)
  c(profile=5.7,spread=4.8,bands=max(5.4,2.1+nrow(bands$values)*.25),peaks=max(4.5,2.2+length(records)*.5))
}
chart_frame <- function(title,subtitle,mar=c(4.5,5,4,2)) {
  graphics::par(mar=mar,family="sans",col="#20354B",col.axis="#67788A",col.lab="#67788A",bg="white",cex=.9)
}
chart_titles <- function(title,subtitle) {
  graphics::title(main=title,col.main="#14283F",cex.main=1.25,line=2.2)
  graphics::mtext(paste(strwrap(subtitle,width=115),collapse="\n"),side=3,line=.4,cex=.7,col="#67788A")
}
empty_chart <- function(title,message) {
  chart_frame(title,message); graphics::plot.new(); graphics::text(.5,.5,message); chart_titles(title,"")
}
draw_chart <- function(kind,record,channels,stage,records) {
  subtitle <- paste(stage,record$file_name,record$sheet_name,sep=" | ")
  colors <- profile_colors(channels)
  if(kind=="profile") {
    chart_frame("Temperature profile",subtitle,mar=c(5.7,5,4.2,2))
    d <- record$data[record$data$channel %in% channels,]; y <- d$temperature_c[is.finite(d$temperature_c)]
    span <- max(1,diff(range(y)))
    graphics::plot(NA,xlim=c(0,record$duration),ylim=range(y)+c(-.08,.14)*span,
      xlab="Elapsed time (min)",ylab="Temperature (°C)",bty="n",las=1)
    graphics::grid(col="#E5EBF1")
    for(ch in channels) for(s in unique(d$segment[d$channel==ch])) {
      z <- d[d$channel==ch & d$segment==s & is.finite(d$temperature_c),]
      if(nrow(z)) graphics::lines(z$elapsed_min,z$temperature_c,col=colors[ch],lwd=2.2,type=if(nrow(z)==1) "p" else "l",pch=16)
    }
    graphics::legend("bottom",inset=c(0,-.25),legend=channels,col=colors,lwd=2.2,ncol=min(6,length(channels)),bty="n",xpd=NA,cex=.8)
    chart_titles("Temperature profile",subtitle)
  } else if(kind=="spread") {
    d <- spread_data(record,channels)
    if(!any(is.finite(d$value))) return(empty_chart("Channel temperature spread","At least two channels with simultaneous readings are required."))
    chart_frame("Channel temperature spread",subtitle,mar=c(6,5,4,2))
    graphics::plot(NA,xlim=c(0,record$duration),ylim=c(0,max(1,max(d$value,na.rm=TRUE))*1.22),xlab="Elapsed time (min)",ylab="Channel spread (°C)",bty="n",las=1)
    graphics::grid(col="#E5EBF1")
    for(s in unique(d$segment)) {
      z <- d[d$segment==s & is.finite(d$value),]; if(!nrow(z)) next
      graphics::polygon(c(z$time,rev(z$time)),c(z$value,rep(0,nrow(z))),col="#167F831A",border=NA)
      graphics::lines(z$time,z$value,col="#167F83",lwd=2.5,type=if(nrow(z)==1) "p" else "l",pch=16)
    }
    k <- which.max(d$value); graphics::points(d$time[k],d$value[k],col="#D08B4F",pch=16)
    graphics::mtext(sprintf("Maximum %.1f °C at %.2f min | Selected channels: %s",d$value[k],d$time[k],paste(channels,collapse=", ")),side=1,line=4.5,cex=.7)
    chart_titles("Channel temperature spread",subtitle)
  } else if(kind=="bands") {
    d <- band_data(record,channels); nr <- nrow(d$values); nc <- length(channels)
    chart_frame("Time in temperature bands",subtitle,mar=c(5,6,4.3,2))
    graphics::plot(NA,xlim=c(.5,nc+.5),ylim=c(.5,nr+.5),xlab="",ylab="",axes=FALSE,xaxs="i",yaxs="i")
    palette <- grDevices::colorRampPalette(c("#EDF5F5","#83BCB8","#167F83","#123C52"))(101)
    high <- max(1,d$values,na.rm=TRUE)
    for(i in seq_len(nr)) for(j in seq_len(nc)) {
      v <- d$values[i,j]; color <- if(is.finite(v)) palette[1+round(100*v/high)] else "#F1F2F4"
      graphics::rect(j-.5,i-.5,j+.5,i+.5,col=color,border="white",lwd=2)
      graphics::text(j,i,if(is.finite(v)) sprintf("%.1f",v) else "N/A",col=if(is.finite(v)&&v>high*.5) "white" else "#20354B",cex=.85)
    }
    graphics::axis(1,at=seq_len(nc),labels=channels,tick=FALSE)
    graphics::axis(2,at=seq_len(nr),labels=gsub("–","-",d$labels),las=1,tick=FALSE,cex.axis=.75)
    graphics::mtext("Temperature band (°C)",side=2,line=4.3)
    graphics::mtext("Cell values: minutes. Linear interpolation; missing readings and long gaps excluded.",side=1,line=2.8,cex=.7)
    graphics::mtext(paste("Covered time:",paste(paste0(channels," ",sprintf("%.1f",d$coverage)," min"),collapse=" | ")),side=1,line=3.8,cex=.65)
    chart_titles("Time in temperature bands",subtitle)
  } else if(kind=="peaks") {
    d <- peak_data(records); allch <- sort(unique(d$channel)); n <- length(records)
    if(!nrow(d)) return(empty_chart("Peak temperatures by uploaded file","Upload at least one readable file."))
    labels <- vapply(records,function(r) r$file_name,character(1))
    # Wrap long names without dropping text; increase the left margin as needed.
    labels <- vapply(labels,function(x) paste(strwrap(x,35),collapse="\n"),character(1))
    chart_frame("Peak temperatures by uploaded file",subtitle,mar=c(7.2,14,4.3,2))
    span <- max(1,diff(range(d$peak))); offsets <- if(length(allch)==1) 0 else seq(-.26,.26,length.out=length(allch))
    graphics::plot(NA,xlim=range(d$peak)+c(-.12,.2)*span,ylim=c(n+.65,.35),xlab="",ylab="",yaxt="n",bty="n",las=1)
    graphics::abline(h=seq_len(n),col="#E5EBF1")
    graphics::axis(2,at=seq_len(n),labels=labels,las=1,tick=FALSE,cex.axis=.75)
    for(j in seq_along(allch)) {
      z <- d[d$channel==allch[j],]; graphics::points(z$peak,z$index+offsets[j],col=profile_colors(allch[j]),pch=16,cex=1.1)
    }
    graphics::mtext("Peak temperature (°C)",side=1,line=2.4)
    legend_y <- graphics::grconvertY(graphics::grconvertY(graphics::par("usr")[3],from="user",to="inches")-.76,from="inches",to="user")
    graphics::legend(x=mean(graphics::par("usr")[1:2]),y=legend_y,xjust=.5,yjust=.5,legend=allch,col=profile_colors(allch),pch=16,ncol=min(6,length(allch)),bty="n",xpd=NA,cex=.8)
    chart_titles(paste("Peak temperatures |",n,"uploaded file(s)"),paste(stage,"| All active channels; one worksheet per uploaded file"))
    graphics::mtext("Peaks may occur at different times. Matching worksheet name used when available; otherwise the first readable worksheet.",side=1,line=6.1,cex=.6)
  }
}
save_chart_png <- function(file,kind,record,channels,stage,records=list(record)) {
  heights <- chart_heights(record,channels,records)
  grDevices::png(file,width=12,height=heights[kind],units="in",res=160,bg="white")
  on.exit(grDevices::dev.off(),add=TRUE)
  draw_chart(kind,record,channels,stage,records)
}
save_all_charts_png <- function(file,record,channels,stage,records=list(record)) {
  heights <- chart_heights(record,channels,records)
  grDevices::png(file,width=12,height=sum(heights),units="in",res=160,bg="white")
  on.exit(grDevices::dev.off(),add=TRUE)
  graphics::layout(matrix(seq_along(heights),ncol=1),heights=heights)
  for(kind in names(heights)) draw_chart(kind,record,channels,stage,records)
}
save_report_xlsx <- function(file,record,channels,stage,records=list(record)) {
  source <- write_source_sheet(record); wb <- source$wb
  sheet <- if(tolower(source$sheet)=="charts") "Charts (report)" else "Charts"
  openxlsx::addWorksheet(wb,sheet,gridLines=FALSE)
  openxlsx::setColWidths(wb,sheet,cols=1:16,widths=11)
  openxlsx::setRowHeights(wb,sheet,rows=1:5,heights=c(30,26,24,24,24))
  for(i in 1:5) openxlsx::mergeCells(wb,sheet,cols=1:16,rows=i)
  text <- c("BAM Automotive Company",paste(stage,record$file_name,record$sheet_name,sep=" | "),
    "Developed by Nazanin Ghaemi-Zadeh",paste("Visible profile channels:",paste(channels,collapse=", ")),
    paste("Comparison includes",length(records),"uploaded file(s) in this process."))
  openxlsx::writeData(wb,sheet,text,colNames=FALSE)
  openxlsx::addStyle(wb,sheet,openxlsx::createStyle(fgFill="#14283F",fontColour="white",textDecoration="bold",fontSize=17),rows=1,cols=1:16,gridExpand=TRUE)
  openxlsx::addStyle(wb,sheet,openxlsx::createStyle(fontColour="#67788A",fontSize=10),rows=2:5,cols=1:16,gridExpand=TRUE)
  heights <- chart_heights(record,channels,records); row <- 7L; paths <- character()
  on.exit(unlink(paths),add=TRUE)
  for(kind in names(heights)) {
    png <- tempfile(fileext=".png"); paths <- c(paths,png)
    save_chart_png(png,kind,record,channels,stage,records)
    count <- ceiling(heights[kind]*72/15)+2L
    openxlsx::setRowHeights(wb,sheet,rows=seq.int(row,row+count),heights=15)
    openxlsx::insertImage(wb,sheet,png,startRow=row,startCol=1,width=12,height=heights[kind],units="in",dpi=160)
    row <- row+count
  }
  openxlsx::saveWorkbook(wb,file,overwrite=TRUE)
  clean_unused_drawing_links(file)
}

# ----- modules.R -----
stage_ui <- function(id, stage_title) {
  ns <- shiny::NS(id)
  shiny::tabPanel(stage_title, value = id,
    shiny::div(class = "stage-layout",
      shiny::div(class = "upload-panel",
        shiny::p(class = "eyebrow", "01 / DATA SOURCE"),
        shiny::h3(paste(stage_title, "recordings")),
        shiny::p(class = "secondary", "Upload Elcometer Excel exports for this process."),
        shiny::div(class = "upload-control",
          shiny::fileInput(ns("files"), "Excel files", multiple = TRUE,
            accept = c(".xls", ".xlsx"), buttonLabel = "Browse files",
            placeholder = "No files selected", width = "100%")),
        shiny::p(class = "field-note", "Upload one or more files. Additional uploads join the list in this tab. Use × to remove a file."),
        shiny::hr(), shiny::p(class = "eyebrow", "02 / PROFILE CONTROLS"),
        shiny::uiOutput(ns("record_picker")), shiny::uiOutput(ns("worksheet_picker")),
        shiny::uiOutput(ns("channel_picker")), shiny::uiOutput(ns("source_label")),
        shiny::uiOutput(ns("errors"))),
      shiny::div(class = "chart-panel", shiny::uiOutput(ns("content")))))
}

# Stable file IDs keep identical filenames distinct and delete every sheet of a file.
remove_uploaded_file <- function(uploads, records, selected, id) {
  if (!id %in% names(uploads)) return(list(uploads = uploads, records = records, selected = selected))
  old_index <- match(id, names(uploads))
  records <- records[!names(records) %in% uploads[[id]]$ids]
  uploads <- uploads[names(uploads) != id]
  if (identical(selected, id) || is.null(selected) || !selected %in% names(uploads)) {
    selected <- if (length(uploads)) names(uploads)[min(old_index, length(uploads))] else NULL
  }
  list(uploads = uploads, records = records, selected = selected)
}

stage_server <- function(id, stage_title) {
  shiny::moduleServer(id, function(input, output, session) {
    records <- shiny::reactiveVal(list())
    uploads <- shiny::reactiveVal(list())
    selected_file <- shiny::reactiveVal(NULL)
    last_channel_record <- shiny::reactiveVal(NULL)
    failures <- shiny::reactiveVal(character())
    sequence <- 0L
    source_folder <- tempfile("paint_uploads_"); dir.create(source_folder)
    session$onSessionEnded(function() unlink(source_folder, recursive=TRUE))
    load_files <- function(paths, file_names) {
      if (length(paths) + length(uploads()) > 30) { failures("Keep at most 30 workbooks in each process tab."); return(invisible(NULL)) }
      results <- records(); files <- uploads()
      shiny::withProgress(message = "Reading temperature profiles", value = 0, {
        for (i in seq_along(paths)) {
          sequence <<- sequence + 1L
          fid <- paste0("file_", sequence)
          owned_path <- file.path(source_folder, paste0(fid,".",tolower(tools::file_ext(file_names[i]))))
          if (!file.copy(paths[i],owned_path,overwrite=TRUE)) stop("Could not retain the uploaded workbook.")
          imported <- tryCatch(read_elcometer_workbook(owned_path, file_names[i]),
            error = function(e) list(results = list(), errors = paste0(file_names[i], ": ", conditionMessage(e))))
          ids <- if (length(imported$results)) paste0(fid, "_sheet_", seq_along(imported$results)) else character()
          names(imported$results) <- ids
          results <- c(results, imported$results)
          files[[fid]] <- list(name = file_names[i], ids = ids, errors = imported$errors, path=owned_path)
          shiny::incProgress(1 / length(paths), detail = file_names[i])
        }
      })
      records(results); uploads(files); failures(character())
      if (is.null(selected_file()) || !selected_file() %in% names(files)) selected_file(if (length(files)) names(files)[1] else NULL)
      invisible(NULL)
    }
    shiny::observeEvent(input$files, {
      f <- input$files; shiny::req(nrow(f) > 0)
      load_files(f$datapath, f$name)
    }, ignoreNULL = TRUE)
    shiny::observeEvent(input$pick_file, {
      if (input$pick_file %in% names(uploads())) selected_file(input$pick_file)
    }, ignoreInit = TRUE)
    shiny::observeEvent(input$remove_file, {
      removed <- uploads()[[input$remove_file]]
      if(!is.null(removed$path)) unlink(removed$path)
      state <- remove_uploaded_file(uploads(), records(), selected_file(), input$remove_file)
      records(state$records); uploads(state$uploads); selected_file(state$selected)
      if (!length(state$uploads)) failures(character())
      label <- if (!length(state$uploads)) "No files selected" else if (length(state$uploads) == 1) state$uploads[[1]]$name else paste(length(state$uploads), "files uploaded")
      session$sendCustomMessage("paint-upload-label", list(id = session$ns("files"), label = label))
    }, ignoreInit = TRUE)

    output$record_picker <- shiny::renderUI({
      files <- uploads(); active <- selected_file()
      if (!length(files)) return(shiny::p(class = "field-note", "Your uploaded files will appear here."))
      shiny::div(class = "uploaded-list", role = "group", `aria-label` = "Uploaded files",
        lapply(names(files), function(fid) {
          f <- files[[fid]]; chosen <- identical(active, fid)
          event <- function(name) sprintf("Shiny.setInputValue('%s','%s',{priority:'event'});", session$ns(name), fid)
          shiny::div(class = paste("uploaded-row", if (chosen) "is-selected" else ""),
            shiny::tags$button(type = "button", class = "uploaded-select", title = f$name,
              `aria-pressed` = if (chosen) "true" else "false", onclick = event("pick_file"), f$name),
            shiny::tags$button(type = "button", class = "uploaded-remove", title = paste("Remove", f$name),
              `aria-label` = paste("Remove", f$name), onclick = event("remove_file"), "×"))
        }))
    })
    output$worksheet_picker <- shiny::renderUI({
      fid <- selected_file(); files <- uploads()
      if (is.null(fid) || !fid %in% names(files)) return(NULL)
      ids <- files[[fid]]$ids
      if (length(ids) <= 1) return(NULL)
      available <- records()[ids]
      labels <- vapply(available, function(r) r$sheet_name, character(1))
      selected <- shiny::isolate(input$worksheet)
      if (is.null(selected) || !selected %in% ids) selected <- ids[1]
      shiny::selectInput(session$ns("worksheet"), "Worksheet", choices = stats::setNames(ids, labels), selected = selected)
    })
    current <- shiny::reactive({
      files <- uploads(); fid <- selected_file()
      shiny::req(!is.null(fid), fid %in% names(files))
      ids <- files[[fid]]$ids; shiny::req(length(ids) > 0)
      chosen <- input$worksheet
      if (is.null(chosen) || !chosen %in% ids) chosen <- ids[1]
      records()[[chosen]]
    })
    output$channel_picker <- shiny::renderUI({
      fid <- selected_file(); files <- uploads()
      if (is.null(fid) || !fid %in% names(files) || !length(files[[fid]]$ids)) return(NULL)
      r <- current()
      key <- paste(fid, r$sheet_name, sep = "::")
      selected <- if (identical(key, shiny::isolate(last_channel_record()))) {
        intersect(names(r$labels), shiny::isolate(input$channels))
      } else names(r$labels)
      last_channel_record(key)
      shiny::checkboxGroupInput(session$ns("channels"), "Visible channels",
        choices = stats::setNames(names(r$labels), unname(r$labels)), selected = selected)
    })
    selected_channels <- shiny::reactive({
      r <- current()
      if (is.null(input$channels)) return(character())
      intersect(names(r$labels), input$channels)
    })
    output$source_label <- shiny::renderUI({
      if (!length(uploads())) return(NULL)
      shiny::div(class = "source-label", paste(length(uploads()), "uploaded file(s)"), shiny::br(), paste(length(records()), "readable worksheet(s)"))
    })
    output$errors <- shiny::renderUI({
      errors <- c(failures(), unlist(lapply(uploads(), function(f) f$errors), use.names = FALSE))
      if (!length(errors)) return(NULL)
      shiny::div(class = "import-errors", role = "alert", shiny::strong("Import notes"), shiny::tags$ul(lapply(errors, shiny::tags$li)))
    })
    output$content <- shiny::renderUI({
      files <- uploads(); fid <- selected_file()
      if (!length(files)) return(shiny::div(class = "empty-state",
        shiny::div(class = "empty-mark", "°C"), shiny::p(class = "eyebrow", paste(toupper(stage_title), "WORKSPACE")),
        shiny::h2("Every channel. One clear view."), shiny::p("Upload your Excel files, then select a file from the list on the left."),
        shiny::div(class = "empty-steps", shiny::span("01  Upload Excel"), shiny::span("02  Select a file"), shiny::span("03  Explore your profile"))))
      if (is.null(fid) || !fid %in% names(files)) return(NULL)
      if (!length(files[[fid]]$ids)) return(shiny::div(class = "empty-state", shiny::h2("No readable worksheets"),
        shiny::p("Review the import notes for this file, or choose another uploaded file.")))
      ns <- session$ns
      shiny::tagList(shiny::uiOutput(ns("heading")), shiny::uiOutput(ns("metrics")), shiny::uiOutput(ns("data_notes")),
        plotly::plotlyOutput(ns("profile"), height = "540px"),
        shiny::div(class="analysis-card", shiny::h3("Channel temperature spread"),
          shiny::p(class="field-note", "Highest minus lowest temperature at the same reading, across selected channels. Air is included when selected."),
          plotly::plotlyOutput(ns("spread"),height="370px")),
        shiny::div(class="analysis-card", shiny::h3("Time in temperature bands"),
          shiny::p(class="field-note", "Minutes in each band, estimated by linear interpolation. Missing readings and long gaps are excluded; darker cells mean more time."),
          shiny::uiOutput(ns("bands_container")),shiny::textOutput(ns("band_coverage"))),
        shiny::div(class="analysis-card", shiny::h3("Peak temperatures by uploaded file"),
          shiny::p(class="field-note", "All active channels across uploaded files in this process. Uses the matching worksheet name where available, otherwise the first readable worksheet."),
          shiny::uiOutput(ns("peaks_container"))),
        shiny::div(class = "chart-actions", shiny::downloadButton(ns("download_xlsx"), "Download Excel"),
          shiny::downloadButton(ns("download_png"), "Download all charts (PNG)")),
        shiny::p(class = "field-note export-note", "Excel has two sheets: the selected source worksheet, recolored, and all four charts. PNG contains the same four charts and uses the same colors."),
        shiny::h3(class="section-title", "Uploaded worksheet"),
        shiny::p(class="field-note", "Original sections, fields and values in source order. Blank cells remain blank. Scroll the readings table to view every row."),
        shiny::uiOutput(ns("source_sections")),
        shiny::tags$details(class="method-details",shiny::tags$summary("Calculated channel summary"),
          shiny::p(class="field-note",summary_method),
          shiny::div(class="summary-table calculated-table",shiny::tableOutput(ns("summary")))))
    })

    output$heading <- shiny::renderUI({
      r <- current()
      shiny::div(class = "chart-heading", shiny::div(shiny::p(class = "eyebrow", paste(stage_title, " / TEMPERATURE PROFILE")),
        shiny::h2(r$project), shiny::p(class = "secondary", paste(format(r$start, "%H:%M:%S", tz = "UTC"), "-", format(r$end, "%H:%M:%S", tz = "UTC"), " | ", r$file_name))),
        shiny::span(class = "device-label", r$device))
    })
    output$metrics <- shiny::renderUI({
      r <- current(); channels <- selected_channels()
      metric <- function(label, value) shiny::div(class = "metric", shiny::span(label), shiny::strong(value))
      shiny::div(class = "metrics", metric("Recorded duration", paste(format(round(r$duration, 2), trim = TRUE), "min")),
        metric("Time samples", r$reading_count), metric("Visible channels", length(channels)),
        metric("Median interval", paste(format(round(r$interval_seconds, 2), trim = TRUE), "s")))
    })
    output$data_notes <- shiny::renderUI({
      r <- current(); if (!length(r$notes)) return(NULL)
      shiny::div(class = "import-errors", shiny::tags$ul(lapply(r$notes, shiny::tags$li)))
    })
    output$profile <- plotly::renderPlotly({
      shiny::validate(shiny::need(length(selected_channels()) > 0, "Select at least one channel."))
      plotly_profile(current(), selected_channels(), stage_title)
    })
    output$summary <- shiny::renderTable({ channel_summary(current()) }, digits = 2, na = "N/A", rownames = FALSE)
    compared <- shiny::reactive({ comparison_records(uploads(),records(),current()$sheet_name) })
    output$spread <- plotly::renderPlotly({
      shiny::req(length(selected_channels())>0); plotly_spread(current(),selected_channels())
    })
    output$bands_container <- shiny::renderUI({
      shiny::req(length(selected_channels())>0)
      d <- band_data(current(),selected_channels())
      plotly::plotlyOutput(session$ns("bands"),height=paste0(max(420,180+25*nrow(d$values)),"px"))
    })
    output$bands <- plotly::renderPlotly({
      shiny::req(length(selected_channels())>0); plotly_bands(current(),selected_channels())
    })
    output$band_coverage <- shiny::renderText({
      shiny::req(length(selected_channels())>0)
      d <- band_data(current(),selected_channels())
      paste("Covered time:",paste(paste0(selected_channels()," ",sprintf("%.2f",d$coverage)," min"),collapse=" · "))
    })
    output$peaks_container <- shiny::renderUI({
      plotly::plotlyOutput(session$ns("peaks"),height=paste0(max(360,180+50*length(compared())),"px"))
    })
    output$peaks <- plotly::renderPlotly({ plotly_peaks(compared()) })
    output$source_sections <- shiny::renderUI({
      r <- current()
      shiny::tagList(lapply(source_sections(r),function(section) {
        shiny::div(class="source-section",shiny::h4(section$title),source_table_ui(r,section))
      }))
    })
    file_stem <- shiny::reactive({
      paste0(gsub("[^A-Za-z0-9_-]", "_", stage_title), "_", gsub("[^A-Za-z0-9_.-]", "_", tools::file_path_sans_ext(current()$file_name)))
    })
    output$download_png <- shiny::downloadHandler(filename = function() paste0(file_stem(), "_all_charts.png"), contentType = "image/png",
      content = function(file) { shiny::req(length(selected_channels()) > 0); save_all_charts_png(file, current(), selected_channels(), stage_title, compared()) })
    output$download_xlsx <- shiny::downloadHandler(filename = function() paste0(file_stem(), "_report.xlsx"),
      contentType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      content = function(file) {
        shiny::req(length(selected_channels()) > 0)
        save_report_xlsx(file, current(), selected_channels(), stage_title, compared())
      })
    list(records = records, uploads = uploads, current = current, channels = selected_channels)
  })
}


