company_logo_uri <- "data:image/png;base64,"

app_css <- paste0(app_css, "\n.analysis-card { margin:24px 0; padding:22px 16px; border:1px solid #e4eaf0; border-radius:12px; background:#fff; }\n.analysis-card h3 { margin:0 0 10px; font-size:18px; font-weight:650; color:#14283f; }\n.analysis-card .shiny-text-output { font-size:11px; color:#67788a; margin-top:12px; }\n.source-section { margin:18px 0; border:1px solid #e4eaf0; border-radius:10px; overflow:hidden; }\n.source-section h4 { background:#14283f; color:white; padding:14px 18px; margin:0; font-size:14px; font-weight:600; }\n.source-grid { overflow:auto; }\n.source-grid table { width:100%; margin:0; font-size:12px; }\n.source-grid td,.source-grid th { min-width:45px; white-space:pre-wrap!important; vertical-align:middle!important; }\n.source-grid tr:nth-child(even) { background:#f0f5f8; }\n.source-grid th { background:#e6eff2; color:#20354b; }\n.source-grid td[colspan] { min-width:140px; }\n.source-readings { max-height:550px; }\n.source-readings th { position:sticky; top:0; z-index:1; white-space:nowrap!important; }\n.source-readings td { white-space:nowrap!important; }\n")

ui <- shiny::fluidPage(
  shiny::tags$head(shiny::tags$title("BAM Automotive Company | Temperature Profiles"),
    shiny::tags$meta(name = "viewport", content = "width=device-width, initial-scale=1"),
    shiny::tags$style(shiny::HTML(app_css)),
    shiny::tags$script(shiny::HTML("$(function() {\n  Shiny.addCustomMessageHandler('paint-upload-label', function(message) {\n    var input = document.getElementById(message.id);\n    if (!input) return;\n    var group = input.closest('.shiny-input-container');\n    if (group) {\n      var label = group.querySelector('input[type=\"text\"]');\n      if (label) label.value = message.label;\n    }\n    input.value = '';\n  });\n});"))),
  shiny::div(class = "app-shell",
    shiny::tags$header(class = "app-header",
      shiny::div(class = "header-identity",
        shiny::div(class = "company-logo",
          shiny::tags$img(src = company_logo_uri, alt = "BAM Automotive Company logo")),
        shiny::div(shiny::div(class = "brand", "BAM Automotive Company"),
          shiny::h1("Temperature profiles"),
          shiny::p("Explore oven recordings, one process at a time."))),
      shiny::span(class = "header-tag", "THERMAL DATA WORKSPACE")),
    shiny::tabsetPanel(id = "process", selected = "ed",
      stage_ui("ed", "ED"), stage_ui("primer", "Primer"),
      stage_ui("sealer", "Sealer"), stage_ui("bc", "BC")),
    shiny::tags$footer(class = "app-footer",
      "Developed by Nazanin Ghaemi-Zadeh")))

server <- function(input, output, session) {
  stage_server("ed", "ED")
  stage_server("primer", "Primer")
  stage_server("sealer", "Sealer")
  stage_server("bc", "BC")
}
shiny::shinyApp(ui, server)
